def solve(pts, R, C):
    g=[[0]*C for _ in range(R)]
    for r,c in pts: g[r][c]=2
    # find aligned pair (same row or same col)
    trunk=None
    for i in range(len(pts)):
        for j in range(i+1,len(pts)):
            (r1,c1),(r2,c2)=pts[i],pts[j]
            if r1==r2: trunk=('h',r1)
            if c1==c2: trunk=('v',c1)
    kind,pos=trunk
    for r,c in pts:
        if kind=='h':
            if r==pos:
                for cc in range(min(c for _,c in pts if _[0]==pos)+1, max(c for _,c in pts if _[0]==pos)):
                    g[pos][cc]=3
            else:
                for rr in range(min(r,pos)+1,max(r,pos)): g[rr][c]=3
        else:
            if c==pos:
                for rr in range(min(r for r,_ in pts if _[1]==pos)+1, max(r for r,_ in pts if _[1]==pos)):
                    g[rr][pos]=3
            else:
                for cc in range(min(c,pos)+1,max(c,pos)): g[r][cc]=3
    return g

