def solve(pts, R, C):
    g=[[0]*C for _ in range(R)]
    for r,c in pts: g[r][c]=2
    trunk=None
    for i in range(len(pts)):
        for j in range(i+1,len(pts)):
            (r1,c1),(r2,c2)=pts[i],pts[j]
            if r1==r2: trunk=('h',r1)
            if c1==c2: trunk=('v',c1)
    kind,pos=trunk
    if kind=='h':
        rowpts=[c for r,c in pts if r==pos]
        for cc in range(min(rowpts)+1,max(rowpts)): g[pos][cc]=3
        for r,c in pts:
            if r!=pos:
                for rr in range(min(r,pos)+1,max(r,pos)): g[rr][c]=3
    else:
        colpts=[r for r,c in pts if c==pos]
        for rr in range(min(colpts)+1,max(colpts)): g[rr][pos]=3
        for r,c in pts:
            if c!=pos:
                for cc in range(min(c,pos)+1,max(c,pos)): g[r][cc]=3
    return g

